import { el, button, badge, dateText, modal } from './utils.js';
import { api } from './service.js';
import { openImport, openPackage } from './work-packages.js';
import { openSequence } from './outreach.js';
const canEdit=data=>data.roles?.some(role=>['operator','approver','admin'].includes(role));
function outcome(action){const value=badge(action.state);if(action.state==='succeeded'&&action.kind!=='social.publish')value.textContent=action.kind==='social.connect'?'Request sent':action.kind==='social.comment'?'Comment sent':action.kind==='social.message'?'Message sent':action.kind.startsWith('email.')?'Email sent':'Completed';return value;}
async function actionResult(action){
 const m=modal('Execution result','Native receipts and uncertain outcomes come from the execution record.');m.content.append(el('p',{class:'inline-note',text:'Loading result…'}));m.bottom.append(button('Close',m.close));
 try{const record=await api('action-details',{actionId:action.id});const area=el('div',{class:'review-content'},outcome({...action,state:record.state}),el('p',{text:action.title}),record.state_reason?el('p',{class:'field-help',text:record.state_reason}):null);
 for(const attempt of record.attempts||[])area.append(el('article',{class:'review-entry'},el('strong',{text:`Attempt ${attempt.attempt_no} · ${attempt.outcome}`}),el('p',{text:attempt.receipt?.providerMessageId?`Native identifier: ${attempt.receipt.providerMessageId}`:'No confirmed native receipt for this attempt.'}),attempt.finished_at?el('small',{text:dateText(attempt.finished_at)}):null));
 if(!record.attempts?.length)area.append(el('p',{text:'This action has no delivery attempt yet.'}));m.content.replaceChildren(area);
 }catch(error){m.content.replaceChildren(el('p',{class:'banner error',role:'alert',text:error.message}));}
}
export function renderHome(data,change,refresh,detail) {
 const home=data.home;if(!home?.summary)return el('section',{class:'info-card'},el('h2',{text:'Workspace overview unavailable'}),el('p',{text:'Refresh to retrieve pending reviews, upcoming work and recorded outcomes.'}),button('Retry overview',refresh,'small'));
 const root=el('div',{class:'workspace-summary'});const summary=home.summary;
 root.append(el('div',{class:'summary-row'},...[['Pending approvals',summary.pendingReviews],['Upcoming work',summary.upcoming],['Accounts needing attention',summary.connectionIssues]].map(([name,value])=>el('div',{class:'summary-box',text:name},el('strong',{text:Number(value).toLocaleString()})))));
 const controls=el('div',{class:'toolbar-group'});const upload=button('Import HTML & media',()=>openImport(data,refresh),'primary');upload.disabled=!canEdit(data);controls.append(upload,button('Manage accounts',()=>change('accounts'),'small'));root.append(controls);
 const reviews=el('section',{class:'info-card'},el('h2',{text:'Pending reviews'}));if(!home.pendingReviews.length)reviews.append(el('p',{text:'No unexpired review requests are waiting.'}));
 for(const review of home.pendingReviews){const open=()=>{if(review.kind==='package')void openPackage(review.subjectId,data,refresh);else if(review.kind==='reply')change('inbox','replies');else if(review.kind==='draft'){const action=data.actions.find(a=>a.approvalId===review.id);if(action&&detail)detail(action);else change('drafts');}else change('outreach');};reviews.append(el('article',{class:'dashboard-row'},el('div',{},el('strong',{text:review.name}),el('small',{text:`${review.kind==='reply'?'Separate reply approval':'Exact plan review'} · Decide by ${dateText(review.expiresAt)}`})),button('Review',open,'small')));}
 root.append(reviews);const columns=el('div',{class:'split-panels'});
 for(const [title,items,empty] of [['Upcoming work',home.upcoming,'No approved work is scheduled.'],['Recent outcomes',home.recent,'No outcomes have been recorded.']]){const panel=el('section',{class:'info-card'},el('h2',{text:title}));if(!items.length)panel.append(el('p',{text:empty}));for(const action of items){const open=()=>{const known=data.actions.find(a=>a.id===action.id);if(action.sequenceId)void openSequence(action.sequenceId,data,refresh);else if(known&&detail)detail(known);else void actionResult(action);};panel.append(el('article',{class:'dashboard-row'},el('div',{},outcome(action),el('p',{text:action.title}),el('small',{text:`${action.accountName} · ${action.channel} · ${dateText(title==='Recent outcomes'?action.updatedAt:action.dueAt)}`})),button(title==='Recent outcomes'?'View result':'View details',open,'small')));}columns.append(panel);}root.append(columns);
 const issues=el('section',{class:'info-card'},el('h2',{text:'Connection problems'}));if(!home.connectionIssues.length)issues.append(el('p',{text:'No connected accounts currently report a problem.'}));for(const issue of home.connectionIssues)issues.append(el('article',{class:'dashboard-row'},el('div',{},badge(issue.health),el('p',{text:issue.identity}),el('small',{text:issue.detail||'Open account settings to reconnect and check this identity.'})),button('Open accounts',()=>change('accounts'),'small')));root.append(issues);return root;
}
